"""HTTP client using synchronous requests."""
import requests


def fetch_user(base_url: str, user_id: int) -> dict:
    """Fetch a user by ID. Returns dict with 'id', 'name', 'email'."""
    resp = requests.get(f"{base_url}/users/{user_id}")
    resp.raise_for_status()
    return resp.json()


def fetch_posts(base_url: str, user_id: int) -> list:
    """Fetch posts for a user. Returns list of post dicts."""
    resp = requests.get(f"{base_url}/posts", params={"userId": user_id})
    resp.raise_for_status()
    return resp.json()


def create_post(base_url: str, title: str, body: str, user_id: int) -> dict:
    """Create a new post. Returns the created post dict."""
    resp = requests.post(
        f"{base_url}/posts",
        json={"title": title, "body": body, "userId": user_id},
    )
    resp.raise_for_status()
    return resp.json()
